contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public payable {
        require(true);
        address[] memory tos = new address[](1);
        tos[0] = to;
        bool reverted;
        bytes memory ret;
        (bool s, bytes memory r) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(this), tos, v));
        reverted = !s;
        ret = r;
        assert(reverted);
    }
    // Reject any unknown call so the token (this contract) makes transferFrom fail.
    fallback() external payable {
        revert();
    }
    receive() external payable {}
}

