contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address to, uint v) public payable {
        require(to != address(0));

        // Empty recipient list must revert.
        bool revertedEmpty;
        address[] memory empty = new address[](0);
        try c.transfer(from, token, empty, v) { revertedEmpty = false; }
        catch { revertedEmpty = true; }

        // Non-empty list: if all transferFrom calls succeed, transfer returns true.
        bool revertedNonEmpty;
        bool ok;
        address[] memory tos = new address[](1);
        tos[0] = to;
        try c.transfer(from, token, tos, v) returns (bool r) { revertedNonEmpty = false; ok = r; }
        catch { revertedNonEmpty = true; }

        assert(revertedEmpty && (revertedNonEmpty || ok));
    }

    receive() external payable {}
}

